def shifted(path,line):
 if path not in diffs:
  try:before=subprocess.check_output(['git','show','560b9475f35bbc6e4f5296631298859825091f7f:'+path],stderr=subprocess.DEVNULL,text=True).splitlines()
  except subprocess.CalledProcessError:return line
  after=Path(path).read_text().splitlines() if Path(path).exists() else []
  diffs[path]=difflib.SequenceMatcher(a=before,b=after,autojunk=False).get_opcodes()
 for tag,a,c,d,e in diffs[path]:
  if a<=line-1<c:return d+min(line-1-a,max(0,e-d-1))+1
