   near=re.search(r'`([^`]+)`\s*\($',s[max(0,m.start()-300):m.start()])
   target=byname.get(near[1]) if near else None
  if target is None:
   candidates=oldloc.get((file,line),[]) or oldloc.get((file,line-1),[]) or oldloc.get((file,line+1),[])
   for name in candidates:
